// Feature-based folder structure
// src/app/
//   features/
//     users/
//       index.ts               ← barrel: public API
//       users.routes.ts        ← lazy-loaded routes
//       containers/
//         user-list.component.ts   ← SMART: injects UserStore
//       components/
//         user-card.component.ts   ← DUMB: @Input user; @Output edit
//       services/
//         user.store.ts
//       models/
//         user.model.ts

// SMART component: owns state, injects store
@Component({
  template: \`<user-card *ngFor="let u of store.users()" [user]="u" (edit)="store.openEdit(u)" />\`
})
export class UserListContainer {
  store = inject(UserStore);
}

// DUMB component: pure UI, easily testable
@Component({
  selector: 'user-card',
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: \`<div>{{ user().name }} <button (click)="edit.emit(user())">Edit</button></div>\`
})
export class UserCardComponent {
  user = input.required<User>();
  edit = output<User>();
}

// Global error handler
@Injectable()
export class GlobalErrorHandler implements ErrorHandler {
  private notifications = inject(NotificationService);

  handleError(error: unknown) {
    const message = error instanceof Error ? error.message : String(error);
    this.notifications.showError(message);
    console.error('[GlobalErrorHandler]', error);
  }
}

// SSR-safe: check platform before using browser APIs
@Injectable({ providedIn: 'root' })
export class LocalStorageService {
  private isBrowser = isPlatformBrowser(inject(PLATFORM_ID));

  get(key: string): string | null {
    return this.isBrowser ? localStorage.getItem(key) : null;
  }
}
